# Ported from the upstream mirror's Server Script "wm_payroll_recompute" (API) — logic unchanged.
# Farms / projects / company / approver roles now come from Work Management Settings
# and the Work Management Farm doctype — see work_management/api/config.py.
# REGENERATED by the mirror's port_app.py — edit the mirror script, not this file.

import json

import frappe

from work_management.api.config import get_config


@frappe.whitelist()
def wm_payroll_recompute(**kwargs):
    _cfg = get_config()
    FARM_PROJECT = _cfg["farm_project"]
    DEFAULT_COMPANY = _cfg["default_company"]
    FARMS = _cfg["farms"]
    BLOCK_EXCLUDE = _cfg["block_exclude"]
    FARM_APPROVER_ROLE = _cfg["farm_approver_role"]
    HR_HEAD_ROLES = _cfg["hr_head_roles"]
    STAGE_ROWS = _cfg["stage_rows"]
    STAGE_STATES = _cfg["stage_states"]
    CAPABILITIES = _cfg["capabilities"]
    ALLOW_CONCURRENT_PLANS = _cfg["allow_concurrent_master_plans"]
    ALLOW_SPLIT_DAY = _cfg["allow_split_day"]
    STANDARD_DAY = _cfg["standard_day"]

    # Re-answer count_in_payroll / amount for rows a superseded rule froze.
    #
    # Both are decided once, when an actuals row is written, and never revisited.
    # Change an employee's classification or edit the task-worker lists and every
    # row already recorded keeps the old answer, at zero, silently. wm_payroll_drift
    # reports those rows; this one fixes them, using the rule exactly as it stands.
    #
    # Dry run unless apply=1. Refuses a document that has already been paid.
    #
    #   ?employee=400617                     one person, dry run
    #   ?employee=400617&apply=1             one person, written
    #   ?doc=WMAC-2388386&apply=1            one document
    #   ?from_date=&to_date=&apply=1         a window

    # Only the Employee columns THIS site actually has. Selecting one it has not got
    # is not a blank value, it is (1054, "Unknown column ...") and no recompute at all.
    # A column left out here reads back as None, which is exactly what the
    # qualification test already does with a blank one. frappe.db.has_column is not
    # in the sandbox's globals, but the meta is, and it knows custom fields too.
    R_META = frappe.get_meta("Employee")
    R_PICK = []
    for r_mc in ("employment_type", "designation", "custom_category"):
        if R_META.get_field(r_mc):
            R_PICK.append("e." + r_mc)
    D_COLS = ", ".join(R_PICK)

    rc_apply = frappe.utils.cint(frappe.form_dict.get("apply"))
    rc_emp = frappe.form_dict.get("employee")
    rc_doc = frappe.form_dict.get("doc")
    rc_from = frappe.form_dict.get("from_date")
    rc_to = frappe.form_dict.get("to_date")
    out = {}

    if not (rc_emp or rc_doc or (rc_from and rc_to)):
        out["error"] = "Give an employee, a doc, or a from_date and to_date."
        return out
    else:
        RC_LISTS = [
            ("employment_type", "Work Management Payable Employment Type", "employment_type"),
            ("designation", "Work Management Payable Designation", "designation"),
            ("custom_category", "Work Management Payable Category", "category"),
        ]
        RC_RULE = {}
        for rc_col, rc_child, rc_cfield in RC_LISTS:
            rc_vals = []
            if frappe.db.exists("DocType", rc_child):
                for rc_r in frappe.get_all(rc_child,
                        filters={"parenttype": "Work Management Settings"}, fields=[rc_cfield]):
                    rc_p = str(rc_r.get(rc_cfield) or "").strip()
                    if rc_p:
                        rc_vals.append(rc_p)
            RC_RULE[rc_col] = rc_vals
        out["rule"] = RC_RULE

        rc_conds = "IFNULL(we.count_in_payroll,0) = 0"
        rc_params = {}
        if rc_emp:
            rc_conds = rc_conds + " AND we.employee = %(e)s"
            rc_params["e"] = rc_emp
        if rc_doc:
            rc_conds = rc_conds + " AND we.parent = %(d)s"
            rc_params["d"] = rc_doc
        if rc_from and rc_to:
            rc_conds = rc_conds + " AND we.work_date BETWEEN %(f)s AND %(t)s"
            rc_params["f"] = rc_from
            rc_params["t"] = rc_to

        rc_rows = frappe.db.sql("""
            SELECT we.name, we.parent, we.employee, we.employee_name, we.work_date,
                   we.actual_quantity, we.amount, ac.rate, IFNULL(ac.paid,0) doc_paid,
                   ac.workflow_state, ac.planned_cost""" + \
                   (", " + D_COLS if D_COLS else "") + """
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            LEFT JOIN `tabEmployee` e ON e.name = we.employee
            WHERE """ + rc_conds + """
            ORDER BY we.parent, we.work_date
        """, rc_params, as_dict=True)

        rc_fix = []
        rc_skip = {}
        for rc_r in rc_rows:
            if frappe.utils.cint(rc_r.doc_paid):
                rc_skip["document already paid"] = rc_skip.get("document already paid", 0) + 1
                continue
            rc_pass = 0
            for rc_col in ("employment_type", "designation", "custom_category"):
                if RC_RULE.get(rc_col) and (rc_r.get(rc_col) or "") in RC_RULE[rc_col]:
                    rc_pass = 1
            if not rc_pass:
                rc_skip["employee does not qualify today"] = rc_skip.get("employee does not qualify today", 0) + 1
                continue
            rc_fix.append({
                "row": rc_r.name, "doc": rc_r.parent, "employee": rc_r.employee,
                "employee_name": rc_r.employee_name, "work_date": str(rc_r.work_date),
                "quantity": frappe.utils.flt(rc_r.actual_quantity),
                "was": frappe.utils.flt(rc_r.amount),
                "becomes": round(frappe.utils.flt(rc_r.actual_quantity) * frappe.utils.flt(rc_r.rate), 2),
                "state": rc_r.workflow_state,
            })

        out["rows"] = rc_fix
        out["skipped"] = rc_skip
        out["totals"] = {
            "rows": len(rc_fix),
            "value": round(sum([x["becomes"] for x in rc_fix]), 2),
            "people": len(set([x["employee"] for x in rc_fix])),
            "documents": len(set([x["doc"] for x in rc_fix])),
        }
        out["applied"] = 0

        if rc_apply and rc_fix:
            for rc_f in rc_fix:
                frappe.db.set_value("Work Actuals Employee", rc_f["row"],
                    {"count_in_payroll": 1, "amount": rc_f["becomes"]}, update_modified=False)
            rc_docs = {}
            for rc_f in rc_fix:
                rc_docs[rc_f["doc"]] = 1
            rc_after = []
            for rc_p in rc_docs:
                rc_all = frappe.db.sql("""
                    SELECT employee, actual_quantity, amount, IFNULL(count_in_payroll,0) inp
                    FROM `tabWork Actuals Employee` WHERE parent = %s
                """, (rc_p,), as_dict=True)
                rc_tw = 0
                rc_sal = 0
                rc_pay = 0
                rc_people = []
                rc_paypeople = []
                for rc_x in rc_all:
                    if rc_x.employee not in rc_people:
                        rc_people.append(rc_x.employee)
                    if frappe.utils.cint(rc_x.inp):
                        rc_tw = rc_tw + frappe.utils.flt(rc_x.actual_quantity)
                        if rc_x.employee not in rc_paypeople:
                            rc_paypeople.append(rc_x.employee)
                    else:
                        rc_sal = rc_sal + frappe.utils.flt(rc_x.actual_quantity)
                    rc_pay = rc_pay + frappe.utils.flt(rc_x.amount)
                rc_planned = frappe.utils.flt(frappe.db.get_value("Work Management Actuals", rc_p, "planned_cost"))
                frappe.db.set_value("Work Management Actuals", rc_p, {
                    "total_actual_qty": rc_tw + rc_sal,
                    "custom_tw_qty": rc_tw,
                    "custom_salaried_qty": rc_sal,
                    "actual_people": len(rc_people),
                    "payroll_people": len(rc_paypeople),
                    "total_payment": round(rc_pay, 2),
                    "cost_variance": round(rc_pay - rc_planned, 2),
                }, update_modified=False)
                rc_after.append({"doc": rc_p, "total_payment": round(rc_pay, 2),
                    "payroll_people": len(rc_paypeople), "tw_qty": rc_tw, "salaried_qty": rc_sal})
            frappe.db.commit()
            out["applied"] = 1
            out["documents_updated"] = rc_after

        return out
